"""Category 1 top-up (3): authored multi-turn casual dialogs, more advice, balanced opinions."""
from lib import *

CAT = "general_conversation"
R = seeded("conversation3")
out = []


def lf(s):
    return s[0].lower() + s[1:] if s else s


